`include "disciplines.vams"
module m(u,y,r); input u; output y; inout r; electrical u,y,r; real q; integer valid; analog begin @(initial_step) begin q=0; valid=0; end
            @(timer(0)) valid=1;
            @(timer(0.5)) q=V(y,r)+1;
            V(y,r)<+q*transition(valid,0,1,1); end endmodule
